function countBoundedPairs(nums: number[]): number {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const a = nums[i], b = nums[j];
      const d = Math.abs(a - b), s = Math.abs(a + b);
      if (Math.min(d, s) <= Math.min(Math.abs(a), Math.abs(b)) &&
          Math.max(d, s) >= Math.max(Math.abs(a), Math.abs(b))) count++;
    }
  }
  return count;
}

