class Solution:
    def countBoundedPairs(self, nums: List[int]) -> int:
        count = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                a, b = nums[i], nums[j]
                d, s = abs(a - b), abs(a + b)
                if min(d, s) <= min(abs(a), abs(b)) and max(d, s) >= max(abs(a), abs(b)):
                    count += 1
        return count

