function countBoundedPairs(nums: number[]): number {
  const v = nums.map(Math.abs).sort((x, y) => x - y);
  let count = 0;
  for (let j = 0; j < v.length; j++) {
    let lo = 0, hi = j; // first index with 2·v[i] >= v[j]
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (2 * v[mid] >= v[j]) hi = mid; else lo = mid + 1;
    }
    count += j - lo;
  }
  return count;
}

