        v = sorted(abs(x) for x in nums)
        count = 0
        for j, x in enumerate(v):
            lo, hi = 0, j
            while lo < hi:
                mid = (lo + hi) // 2
                if 2 * v[mid] >= x:
                    hi = mid
                else:
                    lo = mid + 1
            count += j - lo
        return count

